class Solution:
    def validStrings(self, n: int) -> List[str]:
        res = []

        def dfs(cur: list, last_zero: bool):
            if len(cur) == n:
                res.append("".join(cur))
                return
            # append '1' always allowed
            cur.append('1')
            dfs(cur, False)
            cur.pop()
            # append '0' only if previous is not '0'
            if not last_zero:
                cur.append('0')
                dfs(cur, True)
                cur.pop()

        dfs([], False)
        return res
