class Solution:
    def validStrings(self, n: int) -> List[str]:
        res = []

        def dfs(cur: str):
            if len(cur) == n:
                res.append(cur)
                return
            # Appending '1' is always fine
            dfs(cur + "1")
            # Appending '0' is fine only if previous char is '1' or string is empty
            if not cur or cur[-1] == "1":
                dfs(cur + "0")

        dfs("")
        return res

