import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.one_of(
        st.integers(1, 4),
        st.sampled_from([1, 2, 3, 17, 18]),
        st.integers(1, 18),
    ))
    return f"{n}\n"


def validate(inp):
    t = inp.split()
    if len(t) != 1:
        return False
    try:
        n = int(t[0])
    except ValueError:
        return False
    return 1 <= n <= 18


def _valid_set(n):
    res = set()
    for bits in itertools.product("01", repeat=n):
        s = "".join(bits)
        ok = True
        for i in range(n - 1):
            if s[i] == "0" and s[i + 1] == "0":
                ok = False
                break
        if ok:
            res.add(s)
    return res


def ref(inp):
    n = int(inp.split()[0])
    return json.dumps(sorted(_valid_set(n)))


def same(inp, expected, got):
    n = int(inp.split()[0])
    try:
        arr = json.loads(got)
    except Exception:
        return False
    if not isinstance(arr, list):
        return False
    if not all(isinstance(s, str) for s in arr):
        return False
    if len(arr) != len(set(arr)):
        return False
    if not all(len(s) == n and set(s) <= set("01") for s in arr):
        return False
    return set(arr) == _valid_set(n)
